<div class="container-fluid py-3">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h4 text-marsu-burgundy mb-1"><i class="bi bi-diagram-3 me-2"></i><?= e($title) ?></h1><p class="text-muted mb-0">Classify organizations and maintain their accreditation status.</p></div><a href="<?= e(url('orgleadership')) ?>" class="btn btn-outline-secondary"><i class="bi bi-arrow-left me-1"></i>Dashboard</a></div>
    <div class="card shadow-sm border-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Organization</th><th>Category</th><th>Current status</th><th>Accreditation date</th><th class="text-end">Update</th></tr></thead><tbody><?php if (!$organizations): ?><tr><td colspan="5" class="text-center text-muted py-4">No organizations registered yet.</td></tr><?php endif; ?><?php foreach ($organizations as $organization): ?><tr><td><strong><?= e($organization['name']) ?></strong><small class="d-block text-muted"><?= e($organization['acronym']) ?></small></td><td><?= e($organization['category']) ?></td><td><span class="badge <?= $organization['status'] === 'Active' ? 'bg-success' : ($organization['status'] === 'Inactive' ? 'bg-secondary' : 'bg-warning text-dark') ?>"><?= e($organization['status']) ?></span></td><td><?= e($organization['accreditation_date'] ?? '-') ?></td><td class="text-end"><form method="post" action="<?= e(url('orgleadership/organizations/status')) ?>" class="d-flex justify-content-end gap-2"><?= csrf_field() ?><input type="hidden" name="organization_id" value="<?= (int)$organization['id'] ?>"><select class="form-select form-select-sm" name="status" style="max-width:190px" aria-label="Status for <?= e($organization['name']) ?>"><?php foreach ($statuses as $status): ?><option <?= $organization['status'] === $status ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-marsu" type="submit">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
</div>
